mapper.select:
SELECT a.*,
       (SELECT COUNT(*) FROM medical_record m WHERE m.animal_id = a.id AND m.deleted = 0) as medical_count,
       (SELECT COUNT(*) FROM adoption_apply ad WHERE ad.animal_id = a.id AND ad.deleted = 0) as adoption_count
FROM animal a
WHERE a.deleted = 0

    AND a.name LIKE CONCAT('%', #{params.name}, '%')


    AND a.breed = #{params.breed}


    AND a.health_status = #{params.healthStatus}


    AND a.is_neutered = #{params.isNeutered}

ORDER BY a.create_time DESC
